	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/conversations/{id}/cancel", wrapper.CancelTurn)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/conversations/{id}/plan-mode", wrapper.SetPlanMode)
